steps.solutionCode:
const base = {
  describe() {
    return this.name + ' · ' + this.hours + '시간';
  },
};

function makeCourse(name, hours) {
  const course = Object.create(base);

  course.name = name;
  course.hours = hours;
  return course;
}

// 이 함수는 그대로 두세요
function report(name, hours) {
  const c = makeCourse(name, hours);
  return c.describe() + ' / 자기 것: ' + Object.keys(c).join(',') + ' / 물려받음: ' + (c.describe === base.describe);
}

function whereFrom(obj, key) {
  const owns = Object.prototype.hasOwnProperty;
  let current = obj;
  let step = 0;

  while (current !== null) {
    if (owns.call(current, key)) {
      return step === 0 ? '자기 것' : step + '단계 위';
    }
    current = Object.getPrototypeOf(current);
    step += 1;
  }

  return '없음';
}
